const WORD_IN = 1.1;
const WORD_GAP = 0.08;
const WORD_RISE = 0.2;

const clamp01 = (x) => Math.min(1, Math.max(0, x));
const span = (t, at, length) => clamp01((t - at) / Math.max(length, 1e-6));
const expoInOut = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : x < 0.5 ? Math.pow(2, 20 * x - 10) / 2 : (2 - Math.pow(2, -20 * x + 10)) / 2);
const smooth = (x) => x * x * x * (x * (x * 6 - 15) + 10);
const landSoftly = (x) => 1 - Math.pow(1 - x, 5);

function wordIn(t, at) {
  const progress = landSoftly(span(t, at, WORD_IN));
  return { progress, rise: WORD_RISE * (1 - progress), opacity: smooth(span(t, at, WORD_IN * 0.35)) };
}

const LINE = 1.1;
const MOVE = 1.2;
const SHRINK = 0.16;
const OFFSETS = [0.06, -0.08, 0.1, -0.03, 0.07, -0.05];
const ENTRY_GAP = 0.04;
const MAX_WIDTH = 0.5;
const WORD_LAG = 0.55;
const WORD_STAGGER = 0.12;
const WORD_SPACE = 0.18;
const EXIT = 1.2;
const EXIT_PAD = 0.05;
const WORD_EXIT = 0.6;
const WORD_LIFT = 0.12;
const ZOOM = 0.08;
const MAX_CARDS = 12;

const wordsOf = (raw) => String(raw || '').split('/').map((s) => s.trim()).filter(Boolean).slice(0, 2);

function stackLayout(p, width, height) {
  const heroH = Math.min(p.cardHeight * height, (MAX_WIDTH * width) / p.cardAspect);
  const heroW = heroH * p.cardAspect;
  const olderW = heroW * (1 - SHRINK);
  return { heroH, heroW, heroX: (width - heroW) / 2, heroY: (height - heroH) / 2, pitch: olderW * (1 - p.overlap), size: Math.min(p.fontSize * Math.min(width, height), ((height - heroH) / 2) / (LINE + WORD_SPACE)) };
}

function stackFrame(p, t, length, width, height) {
  const n = Math.max(1, Math.min(MAX_CARDS, Math.round(p.cards)));
  const L = stackLayout(p, width, height);
  const arrive = (i) => p.lead + i * p.beat;
  const moved = (i) => expoInOut(span(t, arrive(i), MOVE));
  const out = expoInOut(span(t, length - EXIT_PAD - EXIT, EXIT));
  const away = out * (L.heroX + L.heroW + ENTRY_GAP * width);
  const cards = Array.from({ length: n }, (_, i) => {
    let age = 0;
    for (let j = i + 1; j < n; j++) {
      age += moved(j);
    }
    const settled = Math.min(1, age);
    const scale = 1 - SHRINK * settled;
    const w = L.heroW * scale;
    const h = L.heroH * scale;
    const start = -w - ENTRY_GAP * width;
    const x = start + (L.heroX - start) * moved(i) - age * L.pitch - away;
    const y = height / 2 - h / 2 + OFFSETS[i % OFFSETS.length] * L.heroH * settled;
    const zoom = 1 + ZOOM * (1 - smooth(span(t, arrive(i), length - arrive(i))));
    return { index: i, media: i, x, y, w, h, opacity: 1, zoom };
  });
  const landed = arrive(n - 1) + MOVE * WORD_LAG;
  const fade = smooth(span(t, length - EXIT_PAD - EXIT - WORD_EXIT * 0.5, WORD_EXIT));
  const centre = L.heroX + L.heroW / 2;
  const words = wordsOf(p.words).map((text, k) => {
    const word = wordIn(t, landed + k * WORD_STAGGER);
    const y = k === 0 ? L.heroY - L.size * (LINE + WORD_SPACE) : L.heroY + L.heroH + L.size * WORD_SPACE;
    return { text, x: centre, y, size: L.size, opacity: word.opacity * (1 - fade), rise: word.rise - WORD_LIFT * fade };
  });
  return { cards, words };
}

const VIDEO_MARK = 'video:';
const LINK = /^(https?:|data:|blob:|\/)/;

const picked = (item) => ({ src: item.src, video: item.kind === 'video' });

const mediaList = (raw) => Array.isArray(raw) ? raw.map(picked).filter((m) => m.src) : String(raw || '').split(',').map((s) => s.trim()).filter(Boolean).map((item) => {
  const video = item.startsWith(VIDEO_MARK);
  const id = video ? item.slice(VIDEO_MARK.length).trim() : item;
  const src = LINK.test(id) ? id : assets[id];
  return src ? { src, video } : null;
}).filter(Boolean);

const seekVideo = (video, t) => {
  if (!video || !(video.duration > 0)) {
    return;
  }
  const at = t % video.duration;
  if (Math.abs(video.currentTime - at) > 0.5 / fps) {
    video.currentTime = at;
  }
};

root.insertAdjacentHTML('beforeend', '<div class="sw"></div>');

const scene = root.querySelector('.sw');

let cache = { key: '', cards: [], words: [], lookKey: '' };

const sizeOf = () => ({ width: scene.clientWidth || 1920, height: scene.clientHeight || 1080 });

const mediaHtml = (item) => {
  if (!item) {
    return '';
  }
  return item.video ? '<video muted playsinline preload="auto" src="' + item.src + '"></video>' : '<img decoding="sync" draggable="false" src="' + item.src + '">';
};

const build = (p, f) => {
  const key = JSON.stringify([p.media, f.cards.length, f.words.map((w) => w.text)]);
  if (key === cache.key) {
    return cache;
  }
  const items = mediaList(p.media);
  scene.innerHTML = '';
  const cards = f.cards.map((c) => {
    const node = document.createElement('div');
    node.className = 'sw-card';
    node.innerHTML = mediaHtml(items.length ? items[c.media % items.length] : null);
    scene.appendChild(node);
    const video = node.querySelector('video');
    if (video) {
      video.addEventListener('loadedmetadata', () => seekVideo(video, tl.time()));
    }
    return { node, inner: node.firstElementChild, video };
  });
  const words = f.words.map((w) => {
    const node = document.createElement('div');
    node.className = 'sw-word';
    node.textContent = w.text;
    scene.appendChild(node);
    return node;
  });
  cache = { ...cache, key, cards, words };
  return cache;
};

const paintLook = (p) => {
  const key = JSON.stringify([p.background, p.textColor, p.placeholderColor, p.font, p.fontWeight, p.tracking]);
  if (key === cache.lookKey) {
    return;
  }
  cache = { ...cache, lookKey: key };
  const s = scene.style;
  s.setProperty('--sw-bg', p.background);
  s.setProperty('--sw-ink', p.textColor);
  s.setProperty('--sw-empty', p.placeholderColor);
  s.setProperty('--sw-font', String(p.font).includes(',') ? p.font : '"' + p.font + '", "Helvetica Neue", Helvetica, Arial, sans-serif');
  s.setProperty('--sw-weight', String(p.fontWeight));
  s.setProperty('--sw-tracking', p.tracking + 'em');
};

const paintCard = (card, c, t, width) => {
  const s = card.node.style;
  const visible = c.x + c.w > 0 && c.x < width;
  s.width = c.w + 'px';
  s.height = c.h + 'px';
  s.transform = 'translate3d(' + c.x + 'px, ' + c.y + 'px, 0)';
  s.visibility = visible ? 'visible' : 'hidden';
  if (card.inner) {
    card.inner.style.transform = 'scale(' + c.zoom + ')';
  }
  seekVideo(card.video, t);
};

const paintWord = (s, w) => {
  s.fontSize = w.size + 'px';
  s.left = w.x + 'px';
  s.top = w.y + 'px';
  s.opacity = String(w.opacity);
  s.transform = 'translate3d(-50%, ' + w.rise + 'em, 0)';
  s.visibility = w.opacity > 0.002 ? 'visible' : 'hidden';
};

const draw = () => {
  const p = { ...props };
  const t = tl.time();
  const { width, height } = sizeOf();
  const f = stackFrame(p, t, duration, width, height);
  const nodes = build(p, f);
  paintLook(p);
  f.cards.forEach((c, i) => paintCard(nodes.cards[i], c, t, width));
  f.words.forEach((w, i) => paintWord(nodes.words[i].style, w));
};

draw();
tl.to({}, { duration, ease: 'none', onUpdate: draw }, 0);
